		protected override void DetachButton_Click(object sender, EventArgs e)
		{
			if (!Env.Security.MaintainShipmentAllowDetachingSubShipments.IsAllowed)
			{
				Globals.Message.ShowError(Env.Security.GetErrorMessageForNotAllowed(Env.Security.MaintainShipmentAllowDetachingSubShipments));
				return;
			}

			string message = String.Empty;
			CommonConsol[] consolsToDetach = new CommonConsol[] { };
			List<CommonShipment> selectedShipments = null;

			SelectFirstRowIfOnlyRowInGrid();

			if (ParentShipment != null && InnerGrid.SelectedElements != null && InnerGrid.SelectedElements.Length > 0)
			{
				selectedShipments = InnerGrid.SelectedElements.Cast<CommonShipment>().Where(s => s.IsInDatabase).ToList();
				consolsToDetach = FreightShipmentVsConsolMessageHelper.Instance.GetConsolsToDetachFromSubShipments(out message, null, ParentShipment, null, selectedShipments);
			}

			base.DetachButton_Click(sender, e);

			// Did the shipments detach successfully?
			if (consolsToDetach.Any() && selectedShipments.Any() && !selectedShipments.Intersect(ParentShipment.CoLoadShipments).Any())
			{
				string caption = Res.GetString("66eabd5f-0477-4f8e-80df-f56543599535", "Consols to detach");
				var dialogResult = Globals.Message.Show(message, caption, MessageBoxButtons.YesNo, MessageBoxIcon.Question, DialogResult.No);
				if (dialogResult == DialogResult.Yes)
				{
					StringBuilder allMessages = new StringBuilder();
					foreach (var selectedShipment in selectedShipments)
					{
						var detachRequest = FreightShipmentVsConsolMessageHelper.Instance.IsAllowedToDetachConsols(selectedShipment, consolsToDetach);
						if (!detachRequest.RestrictedMessage.IsEmpty)
						{
							allMessages.AppendLine(detachRequest.RestrictedMessage);
						}
						else
						{
							FreightShipmentVsConsolMessageHelper.Instance.DetachShipmentsFromConsols(new[] { selectedShipment }, consolsToDetach);
						}
					}

					if (allMessages.Length > 0)
					{
						Globals.Message.ShowInformation(allMessages.ToString().TrimEnd(), caption);
					}
				}
				else if (dialogResult == DialogResult.No)
				{
					foreach (var consolToDetach in consolsToDetach)
					{
						consolToDetach.Validation.ValidateJK_AgentType();
					}
				}
			}
		}

