		internal class ShipmentModuleButtonGridAttacher : ZRecordAttacher
		{
			public ShipmentModuleButtonGridAttacher(ForwardingShipment parentShipment, IBusinessObjectCollection destinationCollection, IBusinessObjectCollection findBoxList, ModuleIdentifier moduleID)
				: base(destinationCollection, findBoxList, moduleID)
			{
				this.parentShipment = parentShipment;
			}

			readonly ForwardingShipment parentShipment;

			protected override bool CheckAttaching(List<BusinessObject> businessObjectsToAttach)
			{
				bool result = base.CheckAttaching(businessObjectsToAttach);
				if (result && this.parentShipment != null)
				{
					string caption = Res.GetString("a6ce683e-eaf8-471b-a8d7-e63e896d6399", "Attaching Shipments...");
					var shipmentsToSkip = new List<ForwardingShipment>();
					var skipMessageList = new List<string>();
					string errorMessage;
					foreach (ForwardingShipment shipment in businessObjectsToAttach)
					{
						if (!FreightShipmentVsConsolMessageHelper.Instance.IsAllowedToAttachSubShipment(out errorMessage, this.parentShipment, shipment))
						{
							skipMessageList.Add(errorMessage);
							shipmentsToSkip.Add(shipment);
						}
					}

					if (shipmentsToSkip.Count > 0)
					{
						skipMessageList.Sort();

						string message = Res.GetString("dfeb72db-8277-49aa-a64b-029fa2decbb0",
							"Among of the shipments you are trying to attach to the master-shipment {1}, there are shipments that cannot be attached and will be skipped for the following reasons:{2}{0}",
							string.Join(System.Environment.NewLine, skipMessageList.ToArray()),
							this.parentShipment.JS_UniqueConsignRef,
							System.Environment.NewLine);

						if (Globals.Message.Show(message, caption, MessageBoxButtons.OKCancel, MessageBoxIcon.Warning, DialogResult.Cancel) == DialogResult.Cancel)
						{
							return false;
						}
					}

					foreach (var shipment in shipmentsToSkip)
					{
						businessObjectsToAttach.Remove(shipment);
					}

					result = businessObjectsToAttach.Count > 0;

					// Note: Standalone shipment needs to be added to consol first before default behaviour of adding the shipment to consol in RecordAttacher.
					if (result)
					{
						var subShipments = businessObjectsToAttach.OfType<CommonShipment>().ToList();
						ConsolStandardAloneShipmentRelationshipHelper.AddStandAloneSubShipmentsToMasterShipment(subShipments, this.parentShipment);
					}
				}

				return result;
			}
		}

		protected override bool IsDetachRangeEnabled => true;

		protected override void DetachRange(IEnumerable selectedObjects)
		{
			var args = new ModuleButtonGridOperationCancelEventArgs(null);
			OnDetaching(args);
			if (!args.Cancel)
			{
				var bizOCollection = (BusinessObjectCollection)Collection;
				bizOCollection.RemoveRange(selectedObjects);
				foreach (BusinessObject selected in selectedObjects)
				{
					RemoveWeakReferences(selected);
				}
			}
		}

